<?php
namespace App\Services\Documents;
use App\Support\Database;use App\Support\TenantContext;use App\Support\Auth;
final class DocumentService { public function store(int $clientId,string $name,string $contents,string $mime,?int $businessId=null,?int $projectId=null,bool $sensitive=true):int{$key=TenantContext::id().'/'.date('Y/m').'/'.bin2hex(random_bytes(16));(new PrivateFileStorage)->put($key,$contents);$pdo=Database::pdo();$s=$pdo->prepare('INSERT INTO documents(tenant_id,client_id,business_id,project_id,name,storage_key,is_sensitive,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())');$s->execute([TenantContext::id(),$clientId,$businessId,$projectId,$name,$key,$sensitive?1:0,Auth::id()]);$id=(int)$pdo->lastInsertId();$v=$pdo->prepare('INSERT INTO document_versions(tenant_id,document_id,version_no,storage_key,file_hash,mime_type,size_bytes,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())');$v->execute([TenantContext::id(),$id,1,$key,hash('sha256',$contents),$mime,strlen($contents),Auth::id()]);return $id;} public function access(int $documentId):string{$s=Database::pdo()->prepare('SELECT storage_key FROM documents WHERE tenant_id=? AND id=?');$s->execute([TenantContext::id(),$documentId]);$key=$s->fetchColumn();if(!$key)throw new \RuntimeException('Document not found');$l=Database::pdo()->prepare('INSERT INTO file_access_logs(tenant_id,document_id,user_id,action,ip_address,created_at) VALUES(?,?,?,?,?,NOW())');$l->execute([TenantContext::id(),$documentId,Auth::id(),'read',$_SERVER['REMOTE_ADDR']??null]);return (new PrivateFileStorage)->get($key);}}
